 void SetupOrganisationCaptureG(){world.NewGame(0);world.WalletFunds=100000;world.EnsurePopulationC();world.EnsureOrganisationsG();world.FoundCorporationG();world.DepositCorporationG(20000);world.Hangar["ore"]=1000;organisationTabG=captureScene switch{"stage-g-structures"=>1,"stage-g-territory"=>2,"stage-g-diplomacy"=>3,"stage-g-safety"=>4,_=>0};world.DeployStructureG("Citadel");structureSelectionG=world.Organisations.Structures.Last().Id;world.AdvanceHours(24);corpSelectionG=world.Organisations.Corps.First(c=>c.Npc).Id;if(organisationTabG==4){world.FuelStructureG(structureSelectionG);world.StoreStructureG(structureSelectionG);world.UnanchorStructureG(structureSelectionG);world.AdvanceHours(168);}if(organisationTabG==2){world.SystemId="rim";world.Screen=ViewMode.Station;world.EnsureOrganisationsG();for(int i=0;i<4;i++){world.OrderOperationG("Claim","rim");world.AdvanceHours(1);}world.DeployStructureG("Skyhook");var sky=world.Organisations.Structures.Last();world.AdvanceHours(24);world.Hangar["ore"]=1000;world.FuelStructureG(sky.Id);world.AdvanceHours(2);}desktop.Clear();OpenOrganisationsG();}
 int checksUiG;void RunOrganisationUiChecksG(int frame){void Check(bool ok,string name){if(!ok)throw new Exception("STAGE G UI FAIL / "+name);checksUiG++;Console.WriteLine("STAGE G UI PASS / "+name);}void Click(string tip)=>TestClick(ui.Hits.Last(h=>h.Tip==tip).Rect.Center.ToVector2());switch(frame){case 0:Check(desktop.Any(w=>w.Kind==ViewMode.Organisations),"Organisation window opens");var balance=world.Balance;Click("Stage G deposit");Check(world.Balance==balance-1000,"Deposit button transfers personal funds");Click("Stage G project");Check(world.Organisations.Projects.Count==1,"Project button reserves escrow");break;case 1:Click("Stage G deliver / "+world.Organisations.Projects.Single().Id);Check(world.Organisations.Projects.Single().Paid,"Delivery button pays fulfilled project");Click("Stage G tab / Structures");break;case 2:Click("Stage G fuel");Check(world.Organisations.Structures.Single(s=>s.Corp==world.Organisations.PlayerCorp).State=="Online","Fuel button restores service");Click("Stage G store");Check(world.Organisations.Structures.Single(s=>s.Corp==world.Organisations.PlayerCorp).Assets.GetValueOrDefault("ore")==100,"Storage button consumes real hangar stock");Click("Stage G unanchor");Check(world.Organisations.Structures.Single(s=>s.Corp==world.Organisations.PlayerCorp).State=="Unanchoring","Unanchor button starts saved decommission");Click("Stage G tab / Territory / operations");break;case 3:Click("Stage G operation / Piracy");Check(world.Organisations.Operations.Count==1,"Operation button spends supplies");Click("Stage G wait");Check(world.Organisations.Territories.Single().Corruption==25,"Wait button resolves one saved operation");Click("Stage G tab / Diplomacy / wars");break;case 4:Check(ui.Hits.Any(h=>h.Tip.StartsWith("Stage G diplomat / ")),"Known corporation selection reachable");world.AdvanceHours(167);Click("Stage G tab / Safety / journal");break;case 5:Check(world.Organisations.Journal.Any(j=>j.Contains("Resolved")),"Resolved operation appears in journal");var wrap=world.Organisations.Safety.Last(a=>a.Corp==world.Organisations.PlayerCorp);decimal ore=world.Hangar.GetValueOrDefault("ore");Click("Stage G recovery / "+wrap.Id);Check(wrap.State=="Recovered"&&world.Hangar["ore"]==ore+100,"Recovery button returns actual stored ore once");Console.WriteLine(checksUiG+" Stage G UI checks passed.");break;}}
